    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)
        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''
        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
    if not terms:
        return '0'
    return ''.join(terms)

